  function parseAssignments(src, strict=false){const scope={}; const bad=[]; String(src||'').split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean).forEach(line=>{const m=line.match(/^([A-Za-z_]\w*)\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)$/); if(m)scope[m[1]]=Number(m[2]); else bad.push(line);}); if(strict&&bad.length)throw new Error(`Invalid numeric scope line: ${bad[0]}. Use name=value, for example r=1.`); return scope;}
