  function plotExpression(phase=false){const m=readModel(), expr=selectedExpr(m),xvar=$('symPlotVar')?.value||m.vars[0]||'x',xmin=range('symPlotMin',0),xmax=range('symPlotMax',10),sc=scope(true); if(xmax<=xmin)throw new Error('Invalid x range: x max must be greater than x min.'); const xs=[],ys=[],zeros=[],n=Math.max(100,res()*5); let lx,ly; for(let i=0;i<n;i++){const x=xmin+(xmax-xmin)*i/(n-1); let y=evalExpr(expr,{...sc,[xvar]:x}); if(Number.isFinite(y)){xs.push(x);ys.push(y); if(phase&&ly!==undefined&&y*ly<0)zeros.push((x+lx)/2); lx=x;ly=y;}} if(!xs.length)throw new Error('No finite numeric values were produced. Check the selected expression, x range and numeric scope.'); const traces=[{type:'scatter',mode:'lines',x:xs,y:ys,name:`${expr}`,line:{width:3}},{type:'scatter',mode:'lines',x:[xmin,xmax],y:[0,0],name:'zero',line:{dash:'dash',width:1}}]; if(phase&&zeros.length)traces.push({type:'scatter',mode:'markers',x:zeros,y:zeros.map(()=>0),name:'zero crossings',marker:{size:10,symbol:'x'}}); return {traces,title:phase?'1D RHS and zero crossings':'Expression curve',x:xvar,y:'value'};}
